import React, { useState } from 'react';
import { useAuth } from '@/context/AuthContext';
import { useNavigate } from 'react-router-dom';
import { toast } from 'sonner';

const DEMO_EMAIL = 'admin@cesariglesias.com';
const DEMO_PASSWORD = 'admin123';

const Login = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);

  const { login } = useAuth();
  const navigate = useNavigate();

  // Normaliza input: quita espacios en blanco/invisibles
  const clean = (s) => (s || '').replace(/[\u200B-\u200D\uFEFF]/g, '').trim();

  const handleSubmit = async (e) => {
    e.preventDefault();
    const cleanEmail = clean(email).toLowerCase();
    const cleanPassword = (password || '').replace(/[\u200B-\u200D\uFEFF]/g, '');
    if (!cleanEmail || !cleanPassword) {
      toast.error('Ingrese correo y contraseña');
      return;
    }
    setLoading(true);
    try {
      await login(cleanEmail, cleanPassword);
      toast.success('Inicio de sesión exitoso');
      navigate('/');
    } catch (err) {
      const detail = err?.response?.data?.detail;
      toast.error(typeof detail === 'string' ? detail : 'No se pudo iniciar sesión. Verifique credenciales.');
    } finally {
      setLoading(false);
    }
  };

  const fillDemo = () => {
    setEmail(DEMO_EMAIL);
    setPassword(DEMO_PASSWORD);
    toast.info('Credenciales de admin cargadas. Pulse "Iniciar Sesión".');
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 px-4">
      <div className="max-w-md w-full p-8 bg-white rounded-xl shadow-lg">
        <div className="text-center mb-8">
          <div className="mx-auto h-12 w-12 bg-primary rounded-xl flex items-center justify-center text-white font-black text-2xl">CI</div>
          <h2 className="mt-6 text-3xl font-bold">Iniciar Sesión</h2>
          <p className="text-gray-600 mt-2">Sistema de Gestión de Activos</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6" autoComplete="off">
          <div>
            <label className="block text-sm font-medium mb-1">Correo electrónico</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              autoComplete="username"
              className="w-full px-4 py-3 border rounded-lg focus:outline-none focus:ring-2 focus:ring-primary"
              placeholder="tu@email.com"
              data-testid="login-email-input"
            />
          </div>

          <div>
            <label className="block text-sm font-medium mb-1">Contraseña</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              autoComplete="current-password"
              className="w-full px-4 py-3 border rounded-lg focus:outline-none focus:ring-2 focus:ring-primary"
              placeholder="••••••••"
              data-testid="login-password-input"
            />
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full py-3 bg-primary text-white rounded-lg font-medium hover:bg-primary/90 transition disabled:opacity-50"
            data-testid="login-submit-btn"
          >
            {loading ? 'Iniciando sesión...' : 'Iniciar Sesión'}
          </button>
        </form>

        <div className="mt-6 rounded-lg border border-dashed border-slate-300 bg-slate-50 p-3 text-xs text-slate-600">
          <div className="mb-1.5 font-semibold uppercase tracking-wide text-slate-500">Credenciales de administrador</div>
          <div className="flex items-center justify-between">
            <div className="font-mono">
              <div>Email: <span className="text-slate-900">{DEMO_EMAIL}</span></div>
              <div>Contraseña: <span className="text-slate-900">{DEMO_PASSWORD}</span></div>
            </div>
            <button type="button" onClick={fillDemo}
              className="rounded-md border border-primary/40 bg-white px-3 py-1.5 text-xs font-medium text-primary hover:bg-primary/10"
              data-testid="login-fill-demo-btn">
              Autocompletar
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;
